import{_ as a,c as t,o,ag as n}from"./chunks/framework.DZ_cNctr.js";const s="/docs/screenshots/yokogawa-plate-overview.png",l="/docs/screenshots/yokogawa-plate-panel.png",i="/docs/screenshots/yokogawa-plate-channels.png",r="/docs/screenshots/yokogawa-save-manifest.png",w=JSON.parse('{"title":"Yokogawa CellVoyager plates","description":"Open a Yokogawa CellVoyager CV8000 or CV7000 plate straight from its measurement folder, on the web, in an S3 bucket or on your disk. Move through every well and field without converting anything.","frontmatter":{"title":"Yokogawa CellVoyager plates","description":"Open a Yokogawa CellVoyager CV8000 or CV7000 plate straight from its measurement folder, on the web, in an S3 bucket or on your disk. Move through every well and field without converting anything."},"headers":[],"relativePath":"guides/yokogawa-plates.md","filePath":"guides/yokogawa-plates.md"}'),h={name:"guides/yokogawa-plates.md"};function d(p,e,c,m,g,f){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="yokogawa-cellvoyager-plates" tabindex="-1">Yokogawa CellVoyager plates <a class="header-anchor" href="#yokogawa-cellvoyager-plates" aria-label="Permalink to &quot;Yokogawa CellVoyager plates&quot;">​</a></h1><p>Find Nuclei Viewer opens plates from a Yokogawa CellVoyager CV8000 or CV7000, straight from the measurement folder. Nothing is converted and nothing is uploaded. More than 1,000 JUMP Cell Painting plates in the Cell Painting Gallery come from a CellVoyager CV8000 or CV7000 and open this way.</p><p><img src="'+s+`" alt="JUMP plate 1053601756 from source_2 open in field view on well A/1, field 0, with Hoechst in blue, Concanavalin in green and WGA_Phalloidin in red on the canvas, the Field / Well / Plate toggle with Well and Plate greyed out, the Yokogawa CellVoyager note, the well navigator reading Well A/1, 1 of 384, and the 384-well picker" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>Plates from an Opera Phenix have their own guide: <a href="./opera-phenix-plates.html">Opera Phenix Plates</a>. Other formats the viewer opens are listed in <a href="./supported-formats.html">Supported Formats</a>.</p><h2 id="what-opens" tabindex="-1">What opens <a class="header-anchor" href="#what-opens" aria-label="Permalink to &quot;What opens&quot;">​</a></h2><p>A CellVoyager measurement folder holds three metadata files next to one TIFF per field, plane, timepoint and channel:</p><ul><li><code>MeasurementDetail.mrf</code>: the plate grid, the plate name and the image size.</li><li>the <code>.mes</code> file it names: the channels and their dyes, filters and light sources.</li><li><code>MeasurementData.mlf</code>: one record for every image.</li></ul><p>The viewer reads these files and loads the TIFFs as you look at them. Plates from the CV8000 and the CV7000 both open.</p><p>The folder can sit at any web address that lets the browser read it, such as a public S3 bucket, or on your disk.</p><h2 id="opening-a-plate-from-the-web" tabindex="-1">Opening a plate from the web <a class="header-anchor" href="#opening-a-plate-from-the-web" aria-label="Permalink to &quot;Opening a plate from the web&quot;">​</a></h2><p>Open the <strong>Open</strong> dialog, choose <strong>From URL</strong> and paste one of these:</p><ul><li>the measurement folder, the one that holds <code>MeasurementDetail.mrf</code>,</li><li>the address of <code>MeasurementDetail.mrf</code>,</li><li>or the address of <code>MeasurementData.mlf</code>.</li></ul><p>An <code>https://</code> address and an <code>s3://</code> address both work. Here is JUMP plate 1053601756 from source_2, a CV8000 plate, in both forms:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://cellpainting-gallery.s3.amazonaws.com/cpg0016-jump/source_2/images/20210607_Batch_2/images/1053601756/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>s3://cellpainting-gallery/cpg0016-jump/source_2/images/20210607_Batch_2/images/1053601756/</span></span></code></pre></div><p>The plate opens in field view on well A/1, its first well.</p><p>The viewer looks in the folder you give it, not in the folders below. Some plates sit one level down, inside a folder of the plate&#39;s name. Open that inner folder.</p><p>A bucket name with a dot in it works as <code>s3://</code> in us-east-1. In any other region, paste its regional https address instead: <code>https://s3.&lt;region&gt;.amazonaws.com/&lt;bucket&gt;/...</code>.</p><h2 id="opening-a-plate-from-disk" tabindex="-1">Opening a plate from disk <a class="header-anchor" href="#opening-a-plate-from-disk" aria-label="Permalink to &quot;Opening a plate from disk&quot;">​</a></h2><p>Open the <strong>Open</strong> dialog, go to <strong>Local Files</strong> and click <strong>Choose Data Folder</strong>. Pick the measurement folder, the one that holds <code>MeasurementDetail.mrf</code>. Nothing leaves your computer.</p><p>Folders open in Chrome and Edge, as for any dataset folder. Safari and Firefox cannot open folders. See <a href="./local-files.html">Local Files</a> for the details.</p><h2 id="what-to-expect" tabindex="-1">What to expect <a class="header-anchor" href="#what-to-expect" aria-label="Permalink to &quot;What to expect&quot;">​</a></h2><p>The viewer reads the two small files first, a few kilobytes each. Then it reads the image list, <code>MeasurementData.mlf</code>. The plate opens as soon as the first well is in. The rest of the list, 6 to 10 MB, finishes in the background while you look around.</p><p>Until the list is done, the well picker shows every well of the plate grid. From the next open, it shows exactly the wells that were imaged.</p><h2 id="missing-images" tabindex="-1">Missing images <a class="header-anchor" href="#missing-images" aria-label="Permalink to &quot;Missing images&quot;">​</a></h2><p>A field with no images never shows as black. The canvas says what happened instead:</p><ul><li>From the web: &quot;Images for A/3, field 0 could not be loaded.&quot;</li><li>From disk: &quot;No images for A/3, field 0 in this folder.&quot;</li></ul><p>Opened from disk, the viewer also checks which images the folder holds. That helps with a partial copy of a plate. A well listed in <code>MeasurementData.mlf</code> with no images in the folder is grey in the well picker, with the tooltip &quot;No images in this folder&quot;. Its fields read &quot;(no images)&quot; in the field dropdown.</p><p>One missing channel is left out of that field. The other channels still show.</p><p>The second time, the plate opens faster. The viewer keeps what it learned in the browser&#39;s storage and skips reading the files again. <strong>Clear All Data</strong> on the start screen removes it.</p><h2 id="moving-through-the-plate" tabindex="-1">Moving through the plate <a class="header-anchor" href="#moving-through-the-plate" aria-label="Permalink to &quot;Moving through the plate&quot;">​</a></h2><p>The panel is titled with the plate name, such as 1053601756. The well navigator steps through the wells, and the well picker below it jumps to any of them. The field dropdown moves between fields. The <a href="./hcs-plates.html">HCS Plates</a> guide covers the navigator and picker.</p><p><img src="`+l+'" alt="The Navigation tab of plate 1053601756: Field active and Well and Plate greyed out, the note reading Yokogawa CellVoyager plate: one resolution per field, so Field view only, the well navigator on Well A/1 with the Field 0 dropdown and 1 of 384, and the 384-well picker, 16 by 24" style="max-width:425px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p><strong>Info</strong> in the toolbar names the instrument, for example: &quot;Yokogawa CellVoyager plate (CV8000, TIFF).&quot;</p><h2 id="what-is-shown" tabindex="-1">What is shown <a class="header-anchor" href="#what-is-shown" aria-label="Permalink to &quot;What is shown&quot;">​</a></h2><p><strong>Field view only.</strong> Like an Opera Phenix plate, a CellVoyager plate stores each field at one resolution, with no pyramid. So Plate and Well view are off. The <a href="./opera-phenix-plates.html#why-there-is-no-plate-or-well-view">Opera Phenix guide</a> explains why. Want plate and well views? Convert the plate to OME-Zarr.</p><p><strong>Plane 1 for every channel.</strong> JUMP plates image fluorescence in one plane and brightfield in three. The viewer shows plane 1 of each channel, so every channel of a field shows together. Brightfield&#39;s other planes are not shown yet.</p><p>Field view works as for any image: zoom, pan, channels, contrast.</p><h2 id="channels-and-colours" tabindex="-1">Channels and colours <a class="header-anchor" href="#channels-and-colours" aria-label="Permalink to &quot;Channels and colours&quot;">​</a></h2><p>Channels take their names from the <code>.mes</code> file: Hoechst or MitoTracker on one JUMP plate, DNA or Mito on another. A channel with no name there is named by its filter and light source, such as &quot;BP445/45 · 405nm&quot;. Each one is coloured by its emission wavelength. Brightfield channels are grey and start switched off, so the first view shows the fluorescence. Turn them on in the channel panel. The <a href="./channels.html">Channels</a> guide covers the rest.</p><p><img src="'+i+'" alt="View Options, Channels (6), on plate 1053601756: Hoechst, Concanavalin and WGA_Phalloidin switched on with their contrast sliders, SYTO and MitoTracker switched off, and the brightfield channel TL, grey, switched off" style="max-width:425px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h2 id="the-plate-manifest" tabindex="-1">The plate manifest <a class="header-anchor" href="#the-plate-manifest" aria-label="Permalink to &quot;The plate manifest&quot;">​</a></h2><p>Behind every CellVoyager plate the viewer builds a plate manifest, the same small JSON file it builds for an Opera Phenix plate. It names the plate, its wells, fields and channels, the image size and pixel size, and the file name of every image. To keep one, open <strong>Info</strong> and click <strong>Save plate manifest</strong>.</p><p><img src="'+r+'" alt="The Image Information dialog for plate 1053601756, series A/1/0: 996 by 996 pixels, uint16, 0.6500 µm pixels, 6 channels, 1 resolution, stored remotely, Format reading Yokogawa CellVoyager plate (CV8000, TIFF), with the Save plate manifest button at the bottom" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>The format is published as a JSON Schema: <a href="https://find-nuclei.github.io/schemas/plate-manifest/v1.json" target="_blank" rel="noreferrer">https://find-nuclei.github.io/schemas/plate-manifest/v1.json</a>.</p><h2 id="try-one" tabindex="-1">Try one <a class="header-anchor" href="#try-one" aria-label="Permalink to &quot;Try one&quot;">​</a></h2><p>The Example Gallery holds six CellVoyager plates from JUMP, under the Cell Painting Gallery source. Open one with a single click.</p><h2 id="does-not-open" tabindex="-1">Does not open <a class="header-anchor" href="#does-not-open" aria-label="Permalink to &quot;Does not open&quot;">​</a></h2><ul><li><strong>Folders without <code>MeasurementDetail.mrf</code>.</strong> In JUMP, 10 source_2 plates and all of source_7 hold TIFFs only, with no metadata files. They do not open yet.</li><li><strong>The Yokogawa CQ1.</strong> It writes a different set of files. Convert it to OME-Zarr first.</li><li><strong>Channels of different image sizes.</strong> The viewer shows the channels of a field together, so they must match. A plate that mixes sizes shows a message and does not open.</li></ul><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Brightfield shows plane 1 only.</li><li>No flat-field correction yet. Images show as recorded.</li><li><code>npm run build:plate-manifest</code> builds manifests for Opera Phenix plates only. For a CellVoyager plate, save the manifest from the viewer.</li><li>The embedded viewer does not open these plates. Use the full viewer.</li></ul>',50)])])}const y=a(h,[["render",d]]);export{w as __pageData,y as default};
